import { readFile, readdir, writeFile } from "node:fs/promises";

const files = (await readdir("supabase/migrations"))
  .filter((name) => /^\d{14}_[a-z_]+\.sql$/.test(name))
  .sort();
const parts = await Promise.all(
  files.map(
    async (name) =>
      `-- Migration: ${name}\n${await readFile(`supabase/migrations/${name}`, "utf8")}`,
  ),
);
const snapshot =
  "-- GENERATED by npm run db:schema. Edit ordered migrations, then regenerate.\n" +
  "-- Supabase SQL Editor bootstrap/upgrade; each migration is transactional. No data is deleted.\n\n" +
  parts.join("\n");
if (process.argv.includes("--check")) {
  if ((await readFile("supabase/schema.sql", "utf8")) !== snapshot)
    throw new Error(
      "supabase/schema.sql is out of date. Run npm run db:schema.",
    );
  console.log("Supabase schema matches ordered migrations.");
} else {
  await writeFile("supabase/schema.sql", snapshot);
  console.log("Generated supabase/schema.sql from ordered migrations.");
}
